<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/auth.php';require_login();if(empty($_SESSION['cart']))redirect('pages/cart.php');$ids=array_keys($_SESSION['cart']);$in=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT p.*,s.business_name FROM products p JOIN smes s ON s.id=p.sme_id WHERE p.id IN ($in) AND p.status='active'");$st->execute($ids);$products=$st->fetchAll();$subtotal=0;foreach($products as $p)$subtotal+=(float)$p['price']*$_SESSION['cart'][$p['id']];$district=$_SESSION['user']['id']?(new PDO('mysql:host=localhost;dbname=smeconnect;charset=utf8mb4','root','', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION])):null;$pageTitle='Checkout';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_protect();$name=clean_input($_POST['buyer_name']??'');$address=clean_input($_POST['address']??'');$dist=clean_input($_POST['district']??'');if(!$name||!$address||!$dist){$error='Please complete all delivery details.';}else{$s=$pdo->prepare('SELECT base_fee,free_delivery_threshold FROM districts WHERE name=?');$s->execute([$dist]);$d=$s->fetch();$fee=$d?(($subtotal >= $d['free_delivery_threshold'])?0:(float)$d['base_fee']):60;$pdo->beginTransaction();try{$code='SC-'.strtoupper(bin2hex(random_bytes(4)));$s=$pdo->prepare('INSERT INTO orders(order_code,user_id,buyer_name,address,district,subtotal,delivery_fee,total) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$code,$_SESSION['user']['id'],$name,$address,$dist,$subtotal,$fee,$subtotal+$fee]);$oid=(int)$pdo->lastInsertId();foreach($products as $p){$q=(int)$_SESSION['cart'][$p['id']];$s=$pdo->prepare('INSERT INTO order_items(order_id,product_id,sme_id,quantity,unit_price) VALUES(?,?,?,?,?)');$s->execute([$oid,$p['id'],$p['sme_id'],$q,$p['price']]);$pdo->prepare('UPDATE products SET stock_quantity=stock_quantity-? WHERE id=? AND stock_quantity>=?')->execute([$q,$p['id'],$q]);}$pdo->prepare('INSERT INTO order_status_log(order_id,status,note) VALUES(?,?,?)')->execute([$oid,'placed','Order placed by buyer']);$pdo->commit();$_SESSION['cart']=[];redirect('pages/confirmation.php?code='.urlencode($code));}catch(Throwable $e){$pdo->rollBack();$error=DEV_MODE?$e->getMessage():'Unable to place order.';}}}$districts=$pdo->query('SELECT name FROM districts ORDER BY name')->fetchAll();include __DIR__.'/../includes/partials/header.php';?><h1>Checkout</h1><?php if(!empty($error)):?><div class="flash-message flash-error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Name<input name="buyer_name" required value="<?=e($_SESSION['user']['full_name'])?>"></label><label>Address<input name="address" required></label><label>District<select name="district" required><?php foreach($districts as $d):?><option><?=e($d['name'])?></option><?php endforeach;?></select></label><p>Subtotal: Rs <?=number_format($subtotal,2)?></p><button class="btn-primary">Place Order</button></form><?php include __DIR__.'/../includes/partials/footer.php';?>